15	package server
16	
17	import (
18		"context"
19		"errors"
20		"fmt"
21		"os"
22		"strings"
23		"sync"
24	
25		pb "github.com/casbin/casbin-server/proto"
26		"github.com/casbin/casbin/v2"
27		"github.com/casbin/casbin/v2/model"
28		"github.com/casbin/casbin/v2/persist"
29	)
30	
31	// Server is used to implement proto.CasbinServer.
32	type Server struct {
33		enforcerMap map[int]*casbin.Enforcer
34		adapterMap  map[int]persist.Adapter
35		muE         sync.RWMutex
36		muA         sync.RWMutex
37	}
38	
39	func NewServer() *Server {
40		s := Server{}
41	
42		s.enforcerMap = map[int]*casbin.Enforcer{}
43		s.adapterMap = map[int]persist.Adapter{}
44	
45		return &s
46	}
47	
48	func (s *Server) getEnforcer(handle int) (*casbin.Enforcer, error) {
49		s.muE.RLock()
50		defer s.muE.RUnlock()
51	
52		if e, ok := s.enforcerMap[handle]; ok {
53			return e, nil
54		} else {
55			return nil, errors.New("enforcer not found")
56		}
57	}
58	
59	func (s *Server) getAdapter(handle int) (persist.Adapter, error) {
60		s.muA.RLock()
61		defer s.muA.RUnlock()
62	
63		if a, ok := s.adapterMap[handle]; ok {
64			return a, nil
65		} else {
66			return nil, errors.New("adapter not found")
67		}
68	}
69	
70	func (s *Server) addEnforcer(e *casbin.Enforcer) int {
71		s.muE.Lock()
72		defer s.muE.Unlock()
73	
74		cnt := len(s.enforcerMap)
75		s.enforcerMap[cnt] = e
76		return cnt
77	}
78	
79	func (s *Server) addAdapter(a persist.Adapter) int {
80		s.muA.Lock()
81		defer s.muA.Unlock()
82	
83		cnt := len(s.adapterMap)
84		s.adapterMap[cnt] = a
85		return cnt
86	}
87	
88	func (s *Server) NewEnforcer(ctx context.Context, in *pb.NewEnforcerRequest) (*pb.NewEnforcerReply, error) {
89		var a persist.Adapter
90		var e *casbin.Enforcer
91	
92		if in.AdapterHandle != -1 {
93			var err error
94			a, err = s.getAdapter(int(in.AdapterHandle))
95			if err != nil {
96				return &pb.NewEnforcerReply{Handler: 0}, err
97			}
98		}
99	
100		if in.ModelText == "" {
101			cfg := LoadConfiguration(getLocalConfigPath())
102			data, err := os.ReadFile(cfg.Enforcer)
103			if err != nil {
104				return &pb.NewEnforcerReply{Handler: 0}, err
105			}
106			in.ModelText = string(data)
107		}
108	
109		if a == nil {
110			m, err := model.NewModelFromString(in.ModelText)
111			if err != nil {
112				return &pb.NewEnforcerReply{Handler: 0}, err
113			}
114	
115			e, err = casbin.NewEnforcer(m, false)
116			if err != nil {
117				return &pb.NewEnforcerReply{Handler: 0}, err
118			}
119		} else {
120			m, err := model.NewModelFromString(in.ModelText)
121			if err != nil {
122				return &pb.NewEnforcerReply{Handler: 0}, err
123			}
124	
125			e, err = casbin.NewEnforcer(m, a)
126			if err != nil {
127				return &pb.NewEnforcerReply{Handler: 0}, err
128			}
129		}
130	
131		e.EnableAcceptJsonRequest(in.EnableAcceptJsonRequest)
132	
133		h := s.addEnforcer(e)
134	
135		return &pb.NewEnforcerReply{Handler: int32(h)}, nil
136	}
137	
138	func (s *Server) NewAdapter(ctx context.Context, in *pb.NewAdapterRequest) (*pb.NewAdapterReply, error) {
139		a, err := newAdapter(in)
140		if err != nil {
141			return nil, err
142		}
143	
144		h := s.addAdapter(a)
145	
146		return &pb.NewAdapterReply{Handler: int32(h)}, nil
147	}
148	
149	func (s *Server) parseParam(param, matcher string) (interface{}, string, error) {
150		if strings.HasPrefix(param, "ABAC::") {
151			attrList, err := resolveABAC(param)
152			if err != nil {
153				return nil, matcher, fmt.Errorf("invalid ABAC parameter: %w", err)
154			}
155			for k, v := range attrList.nameMap {
156				old := "." + k
157				if strings.Contains(matcher, old) {
158					matcher = strings.Replace(matcher, old, "."+v, -1)
159				}
160			}
161			return attrList, matcher, nil
162		} else {
163			return param, matcher, nil
164		}
165	}
166	
167	func (s *Server) Enforce(ctx context.Context, in *pb.EnforceRequest) (*pb.BoolReply, error) {
168		e, err := s.getEnforcer(int(in.EnforcerHandler))
169		if err != nil {
170			return &pb.BoolReply{Res: false}, err
171		}
172		var param interface{}
173		params := make([]interface{}, 0, len(in.Params))
174		m := e.GetModel()["m"]["m"].Value
175	
176		for index := range in.Params {
177			param, m, err = s.parseParam(in.Params[index], m)
178			if err != nil {
179				return &pb.BoolReply{Res: false}, err
180			}
181			params = append(params, param)
182		}
183	
184		res, err := e.EnforceWithMatcher(m, params...)
185		if err != nil {
186			return &pb.BoolReply{Res: false}, err
187		}
188	
189		return &pb.BoolReply{Res: res}, nil
190	}
191	
192	func (s *Server) LoadPolicy(ctx context.Context, in *pb.EmptyRequest) (*pb.EmptyReply, error) {
193		e, err := s.getEnforcer(int(in.Handler))
194		if err != nil {
195			return &pb.EmptyReply{}, err
196		}
197	
198		err = e.LoadPolicy()
199	
200		return &pb.EmptyReply{}, err
201	}
202	
203	func (s *Server) SavePolicy(ctx context.Context, in *pb.EmptyRequest) (*pb.EmptyReply, error) {
204		e, err := s.getEnforcer(int(in.Handler))
205		if err != nil {
206			return &pb.EmptyReply{}, err
207		}
208	
209		err = e.SavePolicy()
210	
211		return &pb.EmptyReply{}, err
212	}
