func extractFromArray2DReply(reply *pb.Array2DReply) [][]string {
	array2d := make([][]string, len(reply.D2))
	for i := 0; i < len(reply.D2); i++ {
		array2d[i] = reply.D2[i].D1
	}

	return array2d
}

