	e2 := newTestEngine(t, "file", tmpPolicy, "testdata/model.conf")
	testGetRoles(t, e2, "carol", []string{"data2_admin"})
	testGetPermissions(t, e2, "carol", [][]string{{"carol", "data5", "read"}})
	testHasPermission(t, e2, "carol", []string{"data5", "read"}, true)
}

