// DeleteUser deletes a user.
// Returns false if the user does not exist (aka not affected).
func (s *Server) DeleteUser(ctx context.Context, in *pb.UserRoleRequest) (*pb.BoolReply, error) {
	e, err := s.getEnforcer(int(in.EnforcerHandler))
	if err != nil {
		return &pb.BoolReply{}, err
	}
	if in.User == "" {
		return &pb.BoolReply{}, errEmptyUser
	}

	ruleRemoved, err := applyPolicyChange(e, func() (bool, error) {
		if len(in.Domain) == 0 {
			// Removes both the grouping policies and the permissions of the user.
			return e.DeleteUser(in.User)
		}
		// Domain-scoped variant: g rules are (user, role, domain) and p rules
		// are (user, domain, ...), so filter accordingly.
		removedG, err := e.RemoveFilteredGroupingPolicy(0, append([]string{in.User, ""}, in.Domain...)...)
		if err != nil {
			return removedG, err
		}
		removedP, err := e.RemoveFilteredPolicy(0, append([]string{in.User}, in.Domain...)...)
		return removedG || removedP, err
	})
	return &pb.BoolReply{Res: ruleRemoved}, err
}

